#include <stdio.h>

int gcd(int a, int b) {
    while (b != 0) {
        int t = a % b;
        a = b;
        b = t;
    }
    return a;
}

int lcm(int a, int b) {
    return a / gcd(a, b) * b;
}

int main(void) {
    printf("gcd(48, 18) = %d\n", gcd(48, 18));
    printf("lcm(48, 18) = %d\n", lcm(48, 18));
    return 0;
}

