#include <stdio.h>

void bubble_sort(int arr[], int n) {
    for (int pass = 0; pass < n - 1; pass++) {
        int swapped = 0;
        for (int i = 0; i < n - 1 - pass; i++) {
            if (arr[i] > arr[i + 1]) {
                int t = arr[i];
                arr[i] = arr[i + 1];
                arr[i + 1] = t;
                swapped = 1;
            }
        }
        if (!swapped) break;
    }
}

int main(void) {
    int nums[] = {64, 34, 25, 12, 22, 11, 90};
    int n = sizeof(nums) / sizeof(nums[0]);

    bubble_sort(nums, n);
    for (int i = 0; i < n; i++) {
        printf(i == 0 ? "%d" : " %d", nums[i]);
    }
    printf("\n");
    return 0;
}

#include <stdio.h>

void print_binary(unsigned int n) {
    if (n == 0) {
        printf("0");
        return;
    }
    char bits[33];
    int len = 0;
    while (n > 0) {
        bits[len++] = (n & 1) ? '1' : '0';
        n >>= 1;
    }
    for (int i = len - 1; i >= 0; i--) {
        putchar(bits[i]);
    }
}

int main(void) {
    unsigned int tests[] = {0, 5, 13, 255};
    for (int i = 0; i < 4; i++) {
        printf("%u = ", tests[i]);
        print_binary(tests[i]);
        printf("\n");
    }
    return 0;
}

