}

#include <stdio.h>

int binary_search(const int arr[], int n, int target) {
    int lo = 0, hi = n - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (arr[mid] == target) return mid;
        if (arr[mid] < target) {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    return -1;
}

int main(void) {
    int nums[] = {2, 5, 8, 12, 16, 23, 38, 56, 72, 91};
    int n = sizeof(nums) / sizeof(nums[0]);
    int targets[] = {23, 7};

    for (int i = 0; i < 2; i++) {
        int idx = binary_search(nums, n, targets[i]);
        if (idx >= 0) {
            printf("%d found at index %d\n", targets[i], idx);
        } else {
            printf("%d not found\n", targets[i]);
        }
    }
    return 0;
}

