def rle(text):
    if not text:
        return ""
    result = []
    current, count = text[0], 1
    for ch in text[1:]:
        if ch == current:
            count += 1
        else:
            result.append(f"{current}{count}")
            current, count = ch, 1
    result.append(f"{current}{count}")
    return "".join(result)


